/* Role previews are product demonstrations, not authorization boundaries. */
const requestedPortal=new URLSearchParams(location.search).get('portal');
let portalRole=['admin','client','therapist'].includes(requestedPortal)?requestedPortal:'client',intakeStep=0,reviewingIntake;
const portalBar=document.createElement('section');portalBar.className='portal-switch';portalBar.innerHTML='<div><strong>One care journey. Three focused views.</strong><small>Role preview · Browser-local sample data · No real patient information</small></div><div class="portal-buttons"><button data-role="client">Client intake</button><button data-role="admin" class="active">Admin workspace</button><button data-role="therapist">Therapist workspace</button></div>';document.querySelector('.notice').after(portalBar);
const portalPanel=document.createElement('section');portalPanel.id='portal-panel';portalPanel.hidden=true;document.querySelector('footer').before(portalPanel);
for(const [view,title] of [['intakes','Intake inbox'],['briefings','Therapist briefings'],['extraction','AI extraction review']]){const b=document.createElement('button');b.dataset.view=view;b.innerHTML=icon(view==='intakes'?'review':'spark')+`<span>${title}</span>`;b.onclick=()=>{currentView=view;render()};document.querySelector('nav').append(b);labels[view]=title}
const intakePanel=document.createElement('section');intakePanel.id='client-portal';intakePanel.hidden=true;document.querySelector('footer').before(intakePanel);
intakePanel.innerHTML=`<div class="client-welcome"><span class="eyebrow">WELCOME TO EERO</span><h1>Let’s take the<br>first step together.</h1><p>A simple introduction helps our team understand what you’re looking for. You can photograph a form or enter the details here.</p><div class="client-emergency">This demonstration is not monitored for urgent help. If you are in immediate danger, call 911. In the U.S., call or text 988 for crisis support.</div></div><div class="intake-card"><div class="intake-progress">${['About you','Your needs','Documents','Review'].map((x,i)=>`<span data-step-marker="${i}"><i>${i+1}</i>${x}</span>`).join('')}</div><form id="client-intake-form"><section data-intake-step="0"><span class="tiny-label">STEP 1 OF 4</span><h2>Who is this support for?</h2><p class="muted">Use fictional details for this sample workspace.</p><label class="field">Client name<input id="intake-name" required maxlength="100" placeholder="e.g. River Sample"></label><div class="form-grid"><label class="field">Age group<select id="intake-age" required><option value="">Select age group</option><option>Under 6</option><option>6–8</option><option>9–11</option><option>12–14</option><option>15–17</option><option>18 or older</option></select></label><label class="field">You are the<select id="intake-relationship"><option>Client</option><option>Parent or caregiver</option><option>Referral coordinator</option></select></label></div><label class="field">Contact name<input id="intake-contact-name" required maxlength="100"></label><div class="form-grid"><label class="field">Email<input id="intake-email" type="email" required placeholder="demo@example.invalid"></label><label class="field">Phone (optional)<input id="intake-phone" type="tel" maxlength="30"></label></div></section><section data-intake-step="1" hidden><span class="tiny-label">STEP 2 OF 4</span><h2>What would you like help with?</h2><label class="field">Main concerns<textarea id="intake-concerns" required maxlength="4000" placeholder="Tell us, in your own words, what brings you here."></textarea></label><label class="field">How long has this been happening?<select id="intake-duration"><option>Not sure</option><option>Less than a month</option><option>1–6 months</option><option>More than 6 months</option></select></label><label class="field">What would you like to change?<textarea id="intake-goals" required maxlength="4000"></textarea></label><div class="form-grid"><label class="field">Preferred service<select id="intake-service"><option>Help me choose</option><option>IIC</option><option>Behavioral Assistance</option><option>Parent Coaching</option><option>BPS Assessment</option><option>Group program</option><option>Youth Mentoring</option><option>Parent Mentoring</option><option>Summer Program Services</option></select></label><label class="field">Preferred contact method<select id="intake-contact-method"><option>Email</option><option>Phone</option></select></label></div></section><section data-intake-step="2" hidden><span class="tiny-label">STEP 3 OF 4</span><h2>Add a document, if you have one.</h2><p class="muted">Optional. Use blank forms or fictional documents. Photos and PDFs, up to 15 MB each.</p><div class="capture-options"><label class="capture-button">◎<strong>Take a photo</strong><small>Use your phone camera</small><input id="intake-camera" type="file" accept="image/*" capture="environment" hidden></label><label class="capture-button">↥<strong>Choose documents</strong><small>Photo or PDF</small><input id="intake-files" type="file" accept="image/*,application/pdf" multiple hidden></label></div><div id="intake-file-list"></div><p class="muted">Files stay in this browser in the demo. AI extraction is not connected to this hosted form.</p></section><section data-intake-step="3" hidden><span class="tiny-label">STEP 4 OF 4</span><h2>Check your introduction.</h2><div id="intake-review-summary"></div><label class="check"><input id="intake-demo-confirm" type="checkbox" required> I am submitting fictional information to try this demonstration.</label><p class="muted">This checkbox is not a clinical consent, HIPAA authorization, or electronic signature.</p></section><div class="intake-form-actions"><button type="button" class="secondary" id="intake-prev">Back</button><span id="intake-step-label"></span><button type="button" class="primary" id="intake-next">Continue →</button><button type="submit" class="primary" id="intake-submit" hidden>Submit sample intake</button></div></form></div><section id="client-receipt" hidden></section>`;
let intakeFiles=[];function intakeValues(){return {name:$('intake-name').value.trim(),age:$('intake-age').value,relationship:$('intake-relationship').value,contactName:$('intake-contact-name').value.trim(),email:$('intake-email').value,phone:$('intake-phone').value,concerns:$('intake-concerns').value.trim(),duration:$('intake-duration').value,goals:$('intake-goals').value.trim(),service:$('intake-service').value,contactMethod:$('intake-contact-method').value}}
function showIntakeStep(){intakePanel.querySelectorAll('[data-intake-step]').forEach(s=>s.hidden=Number(s.dataset.intakeStep)!==intakeStep);intakePanel.querySelectorAll('[data-step-marker]').forEach(s=>s.classList.toggle('current',Number(s.dataset.stepMarker)===intakeStep));$('intake-prev').hidden=intakeStep===0;$('intake-next').hidden=intakeStep===3;$('intake-submit').hidden=intakeStep!==3;$('intake-step-label').textContent=`${intakeStep+1} / 4`;if(intakeStep===3){const v=intakeValues();$('intake-review-summary').innerHTML=`<dl class="intake-summary"><dt>Client</dt><dd>${esc(v.name)} · ${esc(v.age)}</dd><dt>Contact</dt><dd>${esc(v.contactName)} · ${esc(v.email)}</dd><dt>Concerns</dt><dd>${esc(v.concerns)}</dd><dt>Goals</dt><dd>${esc(v.goals)}</dd><dt>Service preference</dt><dd>${esc(v.service)}</dd><dt>Documents</dt><dd>${intakeFiles.length} attached</dd></dl>`}}
$('intake-next').onclick=()=>{const fields=intakePanel.querySelector(`[data-intake-step="${intakeStep}"]`).querySelectorAll('input:not([type=file]),select,textarea');for(const f of fields){if(!f.reportValidity())return}intakeStep=Math.min(3,intakeStep+1);showIntakeStep()};$('intake-prev').onclick=()=>{intakeStep=Math.max(0,intakeStep-1);showIntakeStep()};
function addIntakeFiles(files){for(const f of files){if(f.size>15*1024*1024||!(f.type.startsWith('image/')||f.type==='application/pdf')){toast('Choose an image or PDF up to 15 MB.');continue}intakeFiles.push(f)}$('intake-file-list').innerHTML=intakeFiles.map((f,i)=>`<div class="selected-file">${icon('review')}<span>${esc(f.name)}</span><button type="button" data-intake-remove="${i}" aria-label="Remove ${esc(f.name)}">×</button></div>`).join('')}
$('intake-files').onchange=e=>addIntakeFiles(e.target.files);$('intake-camera').onchange=e=>addIntakeFiles(e.target.files);$('intake-file-list').onclick=e=>{const b=e.target.closest('[data-intake-remove]');if(b){intakeFiles.splice(Number(b.dataset.intakeRemove),1);addIntakeFiles([])}};
function initializeIntakes(){if(!state.intakes)state.intakes=[{id:'DEMO-INTAKE-001',name:'River Sample',age:'9–11',relationship:'Parent or caregiver',contactName:'Caregiver Sample',email:'demo@example.invalid',phone:'',concerns:'Big feelings and difficulties joining school activities.',duration:'1–6 months',goals:'Build confidence and communicate needs more comfortably.',service:'Help me choose',contactMethod:'Email',files:[],status:'New',createdAt:new Date().toISOString(),history:['Fictional example intake created']}];state.staffDemo??=[{id:'demo-therapist-a',name:'Demo therapist A'},{id:'demo-therapist-b',name:'Demo therapist B'}]}
$('client-intake-form').onsubmit=async e=>{e.preventDefault();if(intakeStep!==3||!$('intake-demo-confirm').checked)return;const v=intakeValues();if(!v.name||!v.concerns||!v.goals){toast('Complete the required introduction fields.');return}const item={...v,id:uid(),files:[...intakeFiles],status:'New',createdAt:new Date().toISOString(),history:[`Client sample intake submitted ${new Date().toLocaleString()}`]};state.intakes??=[];state.intakes.push(item);const b=$('intake-submit');b.disabled=true;try{await persist();$('client-intake-form').hidden=true;document.querySelector('.intake-progress').hidden=true;$('client-receipt').hidden=false;$('client-receipt').innerHTML=`<div class="receipt-check">✓</div><h2>Your sample introduction is saved.</h2><p>Reference: <strong>${esc(item.id.slice(0,8).toUpperCase())}</strong></p><p>This demonstration places it in the admin intake inbox in this browser. No email was sent and no clinical team has been notified.</p><button class="primary" id="show-admin-intake">See the admin handoff →</button><button class="secondary" id="new-intake-again">Start another sample</button>`;$('show-admin-intake').onclick=()=>{portalRole='admin';currentView='intakes';render()};$('new-intake-again').onclick=()=>{$('client-intake-form').reset();$('client-intake-form').hidden=false;document.querySelector('.intake-progress').hidden=false;$('client-receipt').hidden=true;intakeFiles=[];addIntakeFiles([]);intakeStep=0;showIntakeStep()};toast('Sample intake saved to admin inbox.')}catch{state.intakes=state.intakes.filter(x=>x.id!==item.id);toast('Could not save the sample intake. Check browser storage.')}finally{b.disabled=false}};
function inboxHTML(){const groups=['New','In review','Assigned'];return `<div class="portal-heading"><span class="tiny-label">ADMIN / INTAKE OPERATIONS</span><h2>A clear handoff from hello to care.</h2><p>Review a submission, confirm its details, choose the service, and assign a sample therapist.</p></div><div class="handoff-strip"><span>Client submission</span><span>Admin verification</span><span>Case & assignment</span><span>Therapist briefing</span></div><div class="intake-board">${groups.map(status=>`<section><h3>${status}<span>${state.intakes.filter(i=>i.status===status).length}</span></h3>${state.intakes.filter(i=>i.status===status).map(i=>`<button class="intake-ticket" data-intake="${esc(i.id)}"><span class="tiny-label">${esc(i.service)}</span><strong>${esc(i.name)}</strong><small>${esc(i.age)} · ${esc(i.relationship)}</small><p>${esc(i.concerns.slice(0,110))}</p><div>${i.files?.length||0} documents <span>Review ↗</span></div></button>`).join('')||'<div class="empty">No intakes in this stage.</div>'}</section>`).join('')}</div>`}
function briefingHTML(){const assigned=state.intakes.filter(i=>i.status==='Assigned');return `<div class="portal-heading"><span class="tiny-label">THERAPIST / PREPARATION</span><h2>The context you need, in one place.</h2><p>Briefings reflect client-reported information. No diagnosis has been established by this workspace.</p></div><div class="therapist-grid">${assigned.map(i=>`<article class="briefing-card"><span class="age-tag">${esc(i.assignedService)} · ${esc(i.age)}</span><h3>${esc(i.name)}</h3><p class="muted">Assigned to ${esc(state.staffDemo.find(s=>s.id===i.therapistId)?.name)}</p><h4>Reported concerns</h4><p>${esc(i.concerns)}</p><h4>Client goals</h4><p>${esc(i.goals)}</p><h4>Questions to clarify</h4><ul><li>When did these experiences start, and how do they affect everyday functioning?</li><li>What support has already helped, and what barriers remain?</li><li>What family, school, cultural, or medical context should be assessed?</li><li>What additional assessment and safety discussion are appropriate?</li></ul><h4>Preparation guidance</h4><p>Confirm the intake details, caregiver authority where relevant, consent requirements, preferred goals, and the clinician’s appropriate assessment approach. Review the original source before using any generated summary.</p><a href="https://www.nimh.nih.gov/health/topics/psychotherapies" target="_blank" rel="noopener">NIMH psychotherapy overview ↗</a><p class="briefing-label">Structured intake briefing · Not AI-generated · Not a treatment plan</p><div class="profile-actions"><button class="secondary" data-brief-case="${esc(i.caseId)}">Open case</button><button class="primary" data-brief-review="${esc(i.id)}">Review briefing</button></div>${i.briefReviewedAt?`<p class="muted">Sample review recorded ${esc(new Date(i.briefReviewedAt).toLocaleString())}</p>`:''}</article>`).join('')||'<div class="empty">Assigned intakes appear here. Open the admin intake inbox to review and assign the sample submission.</div>'}</div>`}
function extractionHTML(){return `<div class="portal-heading"><span class="tiny-label">AI / REVIEW BEFORE USE</span><h2>From captured form to checked information.</h2><p>The AI adapter is implemented for local testing. Hosted extraction is not connected. This example does not analyze your uploaded photos.</p></div><div class="extraction-layout"><article class="source-example"><span class="tiny-label">FICTIONAL SCAN EXAMPLE</span><h3>Sample referral form</h3><dl class="intake-summary"><dt>Client</dt><dd>River Sample</dd><dt>Age group</dt><dd>9–11</dd><dt>Contact email</dt><dd>demo@example.invalid</dd><dt>Concern</dt><dd>Big feelings and difficulties joining school activities.</dd><dt>Goal</dt><dd>Build confidence and communicate needs.</dd></dl><p class="muted">This is a predefined sample, not OCR from an uploaded image.</p><button class="primary" id="load-extraction-example">Preview extraction review</button></article><article id="extraction-draft" class="extraction-draft"><div class="empty">Load the fictional example to explore field verification and corrections.</div></article></div>`}
const intakeDialog=newDialog('admin-intake-dialog','<form id="admin-intake-form"><div class="modal-heading"><div><span class="tiny-label">ADMIN INTAKE REVIEW</span><h2 id="admin-intake-title"></h2></div><button type="button" class="close" aria-label="Close">×</button></div><div id="admin-intake-details"></div><label class="field">Confirmed client label<input id="admin-intake-name" required maxlength="100"></label><label class="field">Route to service<select id="admin-intake-service"><option>IIC</option><option>Behavioral Assistance</option><option>Parent Coaching</option><option>BPS Assessment</option><option>Group program</option><option>Youth Mentoring</option><option>Parent Mentoring</option><option>Summer Program Services</option></select></label><label class="field">Assign sample therapist<select id="admin-intake-therapist" required></select></label><label class="check"><input id="admin-intake-confirm" type="checkbox" required> I checked the intake details in this sample.</label><div class="modal-actions"><button type="button" class="secondary" id="admin-mark-review">Mark in review</button><button class="primary" id="admin-intake-assign">Create case & assign</button></div></form>');
function openIntake(id){reviewingIntake=state.intakes.find(i=>i.id===id);const i=reviewingIntake;$('admin-intake-title').textContent=i.name;$('admin-intake-name').value=i.name;$('admin-intake-service').value=i.assignedService||(['IIC','Behavioral Assistance','Parent Coaching','BPS Assessment','Group program'].includes(i.service)?i.service:'BPS Assessment');$('admin-intake-therapist').innerHTML=state.staffDemo.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if(i.therapistId)$('admin-intake-therapist').value=i.therapistId;$('admin-intake-confirm').checked=false;$('admin-intake-assign').textContent=i.caseId?'Update assignment':'Create case & assign';$('admin-intake-details').innerHTML=`<dl class="intake-summary"><dt>Contact</dt><dd>${esc(i.contactName)} · ${esc(i.email)}</dd><dt>Age / duration</dt><dd>${esc(i.age)} · ${esc(i.duration)}</dd><dt>Reported concerns</dt><dd>${esc(i.concerns)}</dd><dt>Goals</dt><dd>${esc(i.goals)}</dd><dt>Attachments</dt><dd>${(i.files||[]).map((f,index)=>`<button type="button" class="text-link" data-intake-file="${index}">${esc(f.name)} ↗</button>`).join('')||'None'}</dd></dl><p class="muted">Service choice is provisional and must be confirmed by qualified staff. Selecting a service is not a clinical diagnosis.</p>`;$('admin-intake-details').querySelectorAll('[data-intake-file]').forEach(b=>b.onclick=()=>{const f=i.files[Number(b.dataset.intakeFile)],url=URL.createObjectURL(f);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)});intakeDialog.showModal()}
$('admin-mark-review').onclick=async()=>{reviewingIntake.status='In review';reviewingIntake.history.push(`Admin marked in review ${new Date().toLocaleString()}`);await persist();intakeDialog.close()};$('admin-intake-form').onsubmit=async e=>{e.preventDefault();if(!$('admin-intake-confirm').checked)return;const i=reviewingIntake;i.name=$('admin-intake-name').value.trim();if(!i.name)return;i.assignedService=$('admin-intake-service').value;i.therapistId=$('admin-intake-therapist').value;if(!i.caseId){i.caseId=uid();state.cases.push({id:i.caseId,label:`Demo intake · ${i.name}`,service:i.assignedService,intakeId:i.id,therapistId:i.therapistId});state.docs.push({id:uid(),caseId:i.caseId,title:'Client intake introduction',type:'Intake form',date:today(),notes:`Client-reported concerns: ${i.concerns}\nDuration: ${i.duration}\nGoals: ${i.goals}`,status:'Needs review',events:[`Intake routed by admin ${new Date().toLocaleString()}`]});for(const f of i.files||[])state.docs.push({id:uid(),caseId:i.caseId,title:f.name,type:'Referral',date:today(),notes:'Original sample intake attachment. Extraction requires review.',status:'Needs review',blob:f,events:['Attached from sample intake']});state.tasks.push({id:uid(),caseId:i.caseId,title:'Review intake briefing and plan assessment',due:today(),done:false})}else{const c=state.cases.find(c=>c.id===i.caseId);c.label=`Demo intake · ${i.name}`;c.service=i.assignedService;c.therapistId=i.therapistId}i.status='Assigned';i.history.push(`Assigned in sample workspace ${new Date().toLocaleString()}`);await persist();intakeDialog.close();toast('Case created, documents filed, and briefing ready for sample therapist.')};
portalPanel.onclick=async e=>{const i=e.target.closest('[data-intake]'),c=e.target.closest('[data-brief-case]'),b=e.target.closest('[data-brief-review]');if(i)openIntake(i.dataset.intake);if(c)openCase(c.dataset.briefCase);if(b){const x=state.intakes.find(i=>i.id===b.dataset.briefReview);x.briefReviewedAt=new Date().toISOString();await persist();toast('Sample briefing review recorded.')}};
function loadExtractionExample(){const fields=[['Client label','River Sample'],['Age group','9–11'],['Contact email','demo@example.invalid'],['Reported concern','Big feelings and difficulties joining school activities.'],['Client goal','Build confidence and communicate needs.']];$('extraction-draft').innerHTML=`<span class="tiny-label">UNVERIFIED EXTRACTION DRAFT</span><h3>Check every field against the source.</h3><form id="extraction-example-form">${fields.map((x,i)=>`<div class="extract-field"><label class="field">${esc(x[0])}<input value="${esc(x[1])}" required></label><label class="check"><input type="checkbox" required> Verified against sample source</label></div>`).join('')}<p class="muted">No confidence scores are invented. The example must not be used to assess a real client.</p><button class="primary">Confirm sample review</button></form>`;$('extraction-example-form').onsubmit=e=>{e.preventDefault();toast('Sample extraction review confirmed. No clinical record was changed.')}}
const priorPortalRender=render;render=function(){if(!state)return;initializeIntakes();const desired=currentView,special=['intakes','briefings','extraction'].includes(desired);if(special)currentView='overview';priorPortalRender();currentView=desired;document.body.classList.toggle('client-mode',portalRole==='client');intakePanel.hidden=portalRole!=='client';portalPanel.hidden=portalRole==='client'||!special;portalBar.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===portalRole));if(portalRole==='client'){document.querySelector('.hero').hidden=true;document.querySelector('.stats').hidden=true;document.querySelector('.quick-actions').hidden=true;$('home-extras').hidden=true;document.querySelector('.panel').hidden=true;$('extra-panel').hidden=true;$('programs-panel').hidden=true;$('page-title').textContent='Client introduction';$('command-open').hidden=true}else{$('command-open').hidden=false;if(special){document.querySelector('.hero').hidden=true;document.querySelector('.stats').hidden=true;document.querySelector('.quick-actions').hidden=true;$('home-extras').hidden=true;document.querySelector('.panel').hidden=true;$('extra-panel').hidden=true;$('programs-panel').hidden=true;portalPanel.innerHTML=desired==='intakes'?inboxHTML():desired==='briefings'?briefingHTML():extractionHTML();$('page-title').textContent=labels[desired];if(desired==='extraction')$('load-extraction-example').onclick=loadExtractionExample}document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===desired);b.hidden=portalRole==='therapist'&&!['cases','calendar','tasks','briefings','extraction'].includes(b.dataset.view)})}};
portalBar.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{portalRole=b.dataset.role;if(portalRole==='admin')currentView='intakes';if(portalRole==='therapist')currentView='briefings';render()});
const previousExport=$('export-open').onclick;$('export-open').onclick=()=>{toast('Client intake contact details and attached files are excluded from the workspace export.');previousExport()};
if(portalRole==='therapist')currentView='briefings';if(portalRole==='admin'&&requestedPortal)currentView='intakes';
showIntakeStep();if(state)render();
